import java.io.BufferedReader
import java.io.BufferedWriter
import java.io.InputStreamReader
import java.io.OutputStreamWriter
import java.util.StringTokenizer

class Solution {
    fun solve() {
        val n = readInt()
        val m = readInt()

        if (m == 1) {
            write(n - 1)
        } else {
            write(n.toLong() * (m - 1))
        }
    }

    companion object {
        private val reader = BufferedReader(InputStreamReader(System.`in`))
        private val writer = BufferedWriter(OutputStreamWriter(System.out))
        private var tokenizer = StringTokenizer("")

        private fun readToken(): String {
            while (!tokenizer.hasMoreTokens()) {
                tokenizer = StringTokenizer(reader.readLine())
            }
            return tokenizer.nextToken()
        }

        fun readInt(): Int = readToken().toInt()
        fun readLong(): Long = readToken().toLong()
        fun readDouble(): Double = readToken().toDouble()

        fun write(vararg values: Any) {
            writer.write(values.joinToString(" "))
            writer.newLine()
        }

        @JvmStatic
        fun main(args: Array<String>) {
            Solution().solve()
            writer.flush()
            reader.close()
            writer.close()
        }
    }
}

import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c = readByte()
        while (c <= 32 && c != -1) c = readByte()

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var value = 0
        while (c > 32 && c != -1) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value * sign
    }
}

fun main() {
    val scanner = FastScanner()
    val n = scanner.nextInt()
    val m = scanner.nextInt()

    if (m == 1) {
        print(n - 1)
    } else {
        print(n.toLong() * (m - 1))
    }
}

